<?php
function hosting_dns_instruction_records(array $order): array {
    $records=dynamic_dns_records(parse_dns_template(dns_template_settings()['content'],$order['domain']),$order['domain'],(int)$order['customer_id']);$profile=json_decode($order['profile'],true);
    return $records;
}
function hosting_dns_instruction_table(array $order): void { ?>
<div class="table-scroll"><table><thead><tr><th>Typ</th><th>Name beim DNS-Anbieter</th><th>Wert / Ziel</th><th>TTL</th></tr></thead><tbody><?php foreach(hosting_dns_instruction_records($order) as $r): ?><tr><td><?= e($r['fieldType']) ?></td><td><code><?= e($r['subDomain']?:'@') ?></code></td><td class="dns-target"><code><?= e($r['fieldType']==='TXT'?dns_txt_value($r['target']):$r['target']) ?></code></td><td><?= (int)$r['ttl'] ?></td></tr><?php endforeach ?></tbody></table></div>
<p class="small muted">Deine bisherigen NS-Einträge und die Nameserver beim Domainanbieter bleiben unverändert. Die Namen gelten relativ zu <?= e($order['domain']) ?>. Bei Anbietern, die vollständige Namen verlangen, ergänze .<?= e($order['domain']) ?>. Bereits vorhandene Einträge für denselben Namen und Typ prüfen, statt widersprüchliche Werte anzulegen. DNS-Änderungen können bis zu 24 Stunden benötigen.</p>
<?php }
function hosting_order_domain_panel(array $order): void {
    if(!hosting_external_domain($order))return;$v=ensure_hosting_domain_verification($order);$active=(bool)$v['activated_ts']; ?>
<section class="panel form-panel" id="domain-verbinden"><h2>Externe Domain mit deinem Webspace verbinden</h2><p>Deine Domain bleibt bei deinem bisherigen Anbieter. Die Einrichtung in ISPConfig beginnt erst nach deiner Bestätigung, einem öffentlich nachweisbaren Prüf-TXT und erfolgreicher Zahlung.</p>
<?php if($active): ?><p class="notice notice-success">Deine Domain wurde am <?= date('d.m.Y H:i',(int)$v['activated_ts']) ?> geprüft und dem Webspace zugeordnet.</p>
<?php else: ?><h3>1. Prüf-TXT bei deinem Domainanbieter anlegen</h3><dl class="detail-list"><div><dt>Typ</dt><dd>TXT</dd></div><div><dt>Name / Host</dt><dd><code>_orga-consult-verification</code><small>Vollständig: <?= e(hosting_verification_name($v)) ?></small></dd></div></dl><label class="field"><span>TXT-Inhalt (genau übernehmen)</span><textarea readonly rows="3" spellcheck="false"><?= e(hosting_verification_value($v)) ?></textarea></label><p>Der Prüfcode gilt ausschließlich für diese Bestellung und Domain. Die übrigen Einträge findest du unten.</p>
<h3>2. Domainverbindung bestätigen</h3><?php if($v['confirmed_ts']): ?><p>Deine Bestätigung liegt vor. <?= $v['verified_ts']?'Der Prüf-TXT wurde gefunden.':'Der Shop prüft den TXT-Eintrag automatisch alle fünf Minuten.' ?></p><?php endif ?><?php if($v['last_error']): ?><p class="small muted" role="status"><?= e($v['last_error']) ?></p><?php endif ?>
<?php if((int)$v['expires_ts']>=time()): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="hosting_domain_confirm"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="verification_token" value="<?= e($v['token']) ?>"><label class="checkbox-field"><input type="checkbox" name="installation_consent" required><span>Ich habe den Prüf-TXT gesetzt und beauftrage ausdrücklich, <?= e($order['domain']) ?> nach erfolgreicher Prüfung und Zahlung mit meinem Webspace zu verbinden.</span></label><button class="button button-teal">TXT prüfen & Domainverbindung bestätigen</button></form><?php else: ?><p>Der Prüfcode ist abgelaufen. Erzeuge einen neuen Code und ersetze den bisherigen TXT-Inhalt.</p><?php endif ?>
<details><summary>Neuen Prüfcode anfordern</summary><form method="post"><?= csrf() ?><input type="hidden" name="action" value="hosting_domain_rotate"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><p>Der bisherige Prüfcode und die bisherige Bestätigung werden ungültig.</p><button class="button button-outline button-small">Prüfcode erneuern</button></form></details>
<?php endif ?><h3>DNS-Vorlage für deinen Anbieter</h3><?php hosting_dns_instruction_table($order);$profile=json_decode($order['profile'],true);if(!hosting_public_dkim($order['domain'],(int)$order['customer_id'])): ?><p>Den individuellen DKIM-TXT-Eintrag erzeugt ISPConfig nach der Domainprüfung bei der Einrichtung deiner Maildomain. Du findest ihn anschließend hier und unter „Paket verwalten“ und übernimmst ihn bei deinem Domainanbieter.</p><?php endif ?></section>
<?php }
function hosting_service_dns_panel(array $service): void {
    if($service['provider']!=='ispconfig')return;$order=one('SELECT * FROM shop_orders WHERE id=? AND customer_id=?',[(int)($service['meta']['order_id']??0),$service['customer_id']]);$profile=$order?json_decode($order['profile'],true):[];$profile['mail_limit']=(int)$service['meta']['limits']['mail'];$o=['domain'=>$service['meta']['domain'],'customer_id'=>$service['customer_id'],'profile'=>json_encode($profile)];$managed=customer_owns_dns_zone((int)$service['customer_id'],$o['domain']);$entry=one('SELECT * FROM shop_hosting_mail_dns WHERE domain=? AND customer_id=?',[$o['domain'],$service['customer_id']]); ?>
<section class="panel form-panel" id="hosting-dns"><h2><?= $managed?'DNS & DKIM für deinen Webspace':'DNS-Vorlage für deine externe Domain' ?></h2><p><?= $managed?'Für die zugeordnete Shop-Domain übernimmt der Shop den individuellen öffentlichen DKIM-Eintrag aus ISPConfig automatisch in OVH.':'Deine Domain bleibt bei deinem Domainanbieter. Übernimm diese DNS-Einträge dort, damit Website und gebuchte E-Mail-Dienste deinen Webspace verwenden.' ?></p><?php hosting_dns_instruction_table($o); ?>
<?php if($entry): ?><p>DKIM: <?= e(['pending'=>'Veröffentlichung vorgemerkt','running'=>'Wird veröffentlicht','published'=>'Bei OVH veröffentlicht','manual'=>'Bei deinem Domainanbieter als TXT eintragen','needs_action'=>'Abgleich muss geprüft werden'][$entry['state']]??$entry['state']) ?></p><?php if($entry['last_error']): ?><p class="small muted"><?= e($entry['last_error']) ?></p><?php endif ?><?php else: ?><p>Für deine Maildomain ist noch kein öffentlicher DKIM-Eintrag im Shop gespeichert.</p><?php endif ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="hosting_dkim_sync"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><button class="button button-outline">DKIM in ISPConfig prüfen & übernehmen</button></form></section>
<?php }
